// Package delivery is the rewards platform's contract for reward deliverers: plugins, written by the teams owning
// a reward's destination (a wallet, a coupon system), that credit a user with a campaign's reward. Delivery has a
// side effect and a call may fail after it happened (its deadline cuts the request after the destination applied
// it), so the platform retries and every attempt for one user of one campaign carries the same IdempotencyKey,
// which the deliverer hands on so the destination applies the reward once. deliverer_plg.go is generated by the
// line below (`go generate ./...`).
package delivery

//go:generate go run github.com/heynemann/go-plg/cmd/plg gen Deliverer

import "context"

// Reward is one user's reward from one campaign.
type Reward struct {
	// IdempotencyKey is "<campaign>/<user>": the same for every attempt to deliver this reward.
	IdempotencyKey string `json:"idempotencyKey"`
	// Campaign is the ID of the campaign granting the reward.
	Campaign string `json:"campaign"`
	// User is the ID of the user credited.
	User string `json:"user"`
	// Memo describes the reward to the user.
	Memo string `json:"memo"`
	// Points is the amount credited.
	Points int64 `json:"points"`
}

// Receipt is the destination's answer to a delivered reward.
type Receipt struct {
	// ID identifies the credit at the destination.
	ID string `json:"id"`
	// Duplicate reports that the destination had already applied a reward of this IdempotencyKey (an earlier
	// attempt reached it) and did not apply it again: delivered all the same.
	Duplicate bool `json:"duplicate"`
}

// Deliverer delivers rewards to one destination.
//
//plg:limits memory=128MiB timeout=5s pool=1..4
type Deliverer interface {
	// Deliver credits reward.User with reward, once per reward.IdempotencyKey.
	Deliver(ctx context.Context, reward Reward) (Receipt, error)
}
